"""Build a self-contained, offline art coverage browser from verified mappings."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent;HERE=ROOT/'full-game'
m=json.loads((HERE/'coverage.json').read_text(encoding='utf-8'))
rows=[]
for a in m['assets']:
    rows.append({k:a.get(k)for k in ['sourcePath','domain','file','nativeFile','disposition','status']})
data=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
status='全部源图片已核验'if m['status']=='all_source_images_verified'else'全量制作进行中'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>天工仙阵 道家美术全量目录</title>
<style>:root{color-scheme:light;--jade:#135f53;--paper:#f4efdf;--ink:#193d36}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,"Microsoft YaHei",sans-serif}header{padding:28px max(24px,calc((100vw - 1440px)/2));background:#0e4f46;color:#fff7de;border-bottom:3px solid #c8a560}h1{font-size:30px;margin:0 0 9px}header p{margin:7px 0;max-width:1100px}a{color:inherit}main{max-width:1490px;margin:auto;padding:24px}nav{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 16px}nav a{background:#fff9e8;padding:8px 12px;border:1px solid #c9b477;border-radius:8px}.tools{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:14px;background:#e6e7d4;border-radius:12px;position:sticky;top:0;z-index:3}input,select,button{font:inherit;padding:9px;border:1px solid #8caa98;border-radius:7px;background:white;color:var(--ink)}input{flex:1;min-width:220px}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}#counter{margin:16px 0}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(218px,1fr));gap:14px}.card{border:1px solid #cebf93;border-radius:13px;overflow:hidden;background:#fffdf5}.art{height:180px;background:#e4ddc9;display:flex;align-items:center;justify-content:center;padding:12px}.dark .art{background:#142d2b}.art img{max-width:100%;max-height:156px;object-fit:contain;image-rendering:auto}.art.original img{image-rendering:pixelated;max-width:none;max-height:none}.info{padding:12px}strong{display:block;font-size:14px;overflow-wrap:anywhere}.path{font-size:11px;word-break:break-all;color:#4e645a;margin:6px 0}.links{display:flex;gap:12px;font-size:12px}.tag{font-size:11px;display:block;margin:7px 0;color:#5c7061}footer{padding:24px 0;color:#526e60}dialog{max-width:90vw;max-height:90vh;border:2px solid #c7a768;border-radius:14px;background:#efe9d8;color:#173e35}dialog img{max-width:80vw;max-height:73vh;object-fit:contain}dialog button{display:block;margin:0 0 10px}.fallback{font-size:14px;text-align:center}.pager{display:flex;align-items:center;gap:12px;margin:20px 0}</style>
<header><h1>天工仙阵 · 道家 Q 版美术</h1><p>__STATUS__ · 源版本 v160.7 · __COUNT__ / 2368 图片路径</p><p>原生裁片与保持原尺寸的引擎兼容图分别提供。技术遮罩、字体和程序生成效果的保留方式见清单；Windows 桌面美术加载与渲染验收已通过，移动设备及全部游戏流程未作穷尽测试。</p></header>
<main><nav><a href="../exports/index.html">完整 UI 与单位预览</a><a href="items-fx/preview.html">物品与特效动画</a><a href="root-turrets/qa/assembly-contact.jpg">炮塔装配</a><a href="coverage.json">全量覆盖清单</a><a href="runtime-visuals/review.json">字体与程序效果</a></nav>
<div class="tools"><input id="q" aria-label="搜索素材" placeholder="搜索名称、源路径或处理方式"><select id="domain" aria-label="素材类别"><option value="">所有类别</option></select><button id="bg">切换深色底</button><button id="native">显示原生图</button></div><p id="counter"></p><div id="grid"></div><div class="pager"><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div><footer>图片路径一项对应一个原版源文件；同一原生母片可对应尺寸、遮罩或状态派生。目录不把技术复用计作新绘原画。</footer></main><dialog id="zoom"><button id="close">关闭</button><img alt="素材放大预览"><p></p></dialog>
<script>const assets=__DATA__;let page=0,native=false;const size=96,$=id=>document.getElementById(id),labels={'ui-system':'界面与图标','items-fx':'物品与特效','terrain':'地形与环境','root-turrets':'炮塔','units':'单位与部件','blocks':'建筑与管线'};for(const d of [...new Set(assets.map(a=>a.domain))]){const o=document.createElement('option');o.value=d;o.textContent=labels[d]||d;$('domain').append(o)}
function selected(){const q=$('q').value.toLowerCase();return assets.filter(a=>(!$('domain').value||a.domain===$('domain').value)&&[a.sourcePath,a.disposition].join(' ').toLowerCase().includes(q))}
function url(p){return '../'+p.split('/').map(encodeURIComponent).join('/')}
function draw(){const list=selected();page=Math.max(0,Math.min(page,Math.ceil(list.length/size)-1));$('grid').replaceChildren();$('counter').textContent=`当前 ${list.length} 个路径 · ${native?'原生图（有提供时）':'原尺寸兼容图'}`;for(const a of list.slice(page*size,(page+1)*size)){const c=document.createElement('article');c.className='card';const art=document.createElement('div');art.className='art';let f=native&&a.nativeFile?a.nativeFile:a.file;if(/\\.(png|jpe?g|webp|gif|svg)$/i.test(f)){const im=new Image();im.loading='lazy';im.alt=a.sourcePath.split('/').pop();im.src=url(f);im.onclick=()=>{$('zoom').querySelector('img').src=url(f);$('zoom').querySelector('p').textContent=f;$('zoom').showModal()};art.append(im)}else{const x=document.createElement('span');x.className='fallback';x.textContent='平台图标文件 · 下载查看';art.append(x)}const info=document.createElement('div');info.className='info';const title=document.createElement('strong');title.textContent=a.sourcePath.split('/').pop();const path=document.createElement('p');path.className='path';path.textContent=a.sourcePath;const tag=document.createElement('span');tag.className='tag';tag.textContent=a.disposition;const links=document.createElement('div');links.className='links';for(const [label,file]of [['兼容图',a.file],['原生 / 主图',a.nativeFile]])if(file){const l=document.createElement('a');l.href=url(file);l.textContent=label;l.target='_blank';links.append(l)}info.append(title,path,tag,links);c.append(art,info);$('grid').append(c)}$('page').textContent=`${list.length?page+1:0} / ${Math.ceil(list.length/size)}`;$('prev').disabled=page===0;$('next').disabled=(page+1)*size>=list.length}
for(const id of ['q','domain'])$(id).addEventListener('input',()=>{page=0;draw()});$('prev').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};$('bg').onclick=()=>document.body.classList.toggle('dark');$('native').onclick=()=>{native=!native;$('native').textContent=native?'显示兼容图':'显示原生图';draw()};$('close').onclick=()=>$('zoom').close();draw();</script></html>'''
page=page.replace('__STATUS__',status).replace('__COUNT__',str(m['mappedSourceImages'])).replace('__DATA__',data)
page=page.replace('let page=0,native=false','let page=0,native=true').replace('<button id="native">显示原生图','<button id="native">显示兼容图')
(HERE/'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'rows':len(rows),'file':'full-game/index.html'}))
